    // Find the heading "Standard Batting"
    const headings = Array.from(document.querySelectorAll('h2'));
    const heading = headings.find(h => h.textContent.includes('Standard Batting'));
    if (!heading) return null;
    // Find the table after the heading
    let sibling = heading.nextElementSibling;
    while (sibling && sibling.tagName !== 'TABLE') {
        sibling = sibling.nextElementSibling;
    }
    if (!sibling) return null;
    const table = sibling;
    // Extract rows
    const rows = Array.from(table.querySelectorAll('tbody tr'));
    const data = [];
    rows.forEach(row => {
        const cells = Array.from(row.querySelectorAll('td, th'));
        // Check if row contains player data (has a link to player page)
        const playerLink = row.querySelector('td a');
        if (playerLink) {
            const playerName = playerLink.textContent.trim();
            // Find BB and AB cells
            // We need to map column indices
            const headerRow = table.querySelector('thead tr');
            if (!headerRow) return;
            const headers = Array.from(headerRow.querySelectorAll('th'));
            const headerTexts = headers.map(h => h.textContent.trim());
            const bbIndex = headerTexts.indexOf('BB');
            const abIndex = headerTexts.indexOf('AB');
            const rowCells = Array.from(row.querySelectorAll('td'));
            // Adjust indices because rowCells may not include th? Actually rowCells are only td, but we need to consider that row may have th for rowheader
            // Simpler: find cells by index relative to all cells in row (including th?)
            const allCells = Array.from(row.querySelectorAll('td, th'));
            // Find the cell with player name first, then count
            // Let's just get all cell texts and map via header indices
            const cellTexts = allCells.map(c => c.textContent.trim());
            // But need to align with header indices; skip the rowheader (first cell maybe th)
            // Let's use rowCells (td only) which correspond to data columns
            // Determine mapping: rowCells[0] corresponds to Player? Actually rowCells[0] is the first td after the th? In the snapshot, each data row has a th for Rk, then td for Player, Age, etc.
            // So rowCells[0] is Player cell.
            // So we need to map header indices to rowCells indices.
            // Let's create a mapping from header text to index in rowCells.
            // First, get the header row cells (th) texts.
            const headerRowCells = Array.from(headerRow.querySelectorAll('th'));
            const headerMap = {};
            headerRowCells.forEach((th, idx) => {
                headerMap[th.textContent.trim()] = idx;
            });
            // Now get rowCells indices: we have rowCells array of td elements.
            // The first td corresponds to column after Rk? Actually Rk is a th, not td. So rowCells[0] corresponds to Player column (second column).
            // So column offset = 1 (skip Rk).
            // For each header, its data is at index = headerMap[header] - offset.
            const offset = 1; // because Rk is th
            const bbIdx = headerMap['BB'] - offset;
            const abIdx = headerMap['AB'] - offset;
            if (bbIdx >= 0 && abIdx >= 0 && rowCells[bbIdx] && rowCells[abIdx]) {
                const bb = rowCells[bbIdx].textContent.trim();
                const ab = rowCells[abIdx].textContent.trim();
                data.push({ player: playerName, BB: bb, AB: ab });
            }
        }
    });
    return data;
}"}

